
(()=>{'use strict';const M=window.Matchsik,$=s=>document.querySelector(s);$('#lookupForm').onsubmit=async e=>{e.preventDefault();const name=$('#name').value.trim(),phone=$('#phone').value.replace(/\D/g,'');$('#lookupError').innerHTML='';if(name.length<2||phone.length<10){$('#lookupError').innerHTML='<div class="error">이름과 휴대전화 번호를 정확히 입력해 주세요.</div>';return}try{const data=await M.api('/applications/lookup',{method:'POST',body:JSON.stringify({name,phone})});sessionStorage.setItem('matchsik_student_portal',JSON.stringify({createdAt:Date.now(),identity:{name,phone},data}));location.href='/student.html'}catch(err){$('#lookupError').innerHTML=`<div class="error">${M.esc(err.message)}</div>`}}})();
